data.minimal_example:
final store = Store<int>(counterReducer, initialState: 0);

StoreProvider<int>(
  store: store,
  child: MaterialApp(
    home: Scaffold(
      body: StoreConnector<int, String>(
        converter: (store) => store.state.toString(),
        builder: (context, count) {
          return Text('Count: $count');
        },
      ),
    ),
  ),
);
